import * as THREE from 'three/webgpu';
import { texture, positionGeometry, materialNormal } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via context
  const colorMap = ctx.textureLoader.load(config.assets.imageUrl);
  const depthMap = ctx.textureLoader.load(config.assets.depthMapUrl);

  colorMap.colorSpace = THREE.SRGBColorSpace;

  // Create heavily tessellated plane for displacement mapping
  const geometry = new THREE.PlaneGeometry(1, 0.625, 64, 64);

  // NodeMaterial with TSL displacement node
  const material = new THREE.NodeMaterial();

  // TSL displacement calculation: depth map R channel * strength * surface normal
  const depthSample = texture(depthMap);
  const displacementStrength = 0.05;
  const displacedPosition = positionGeometry.add(
    depthSample.r.mul(displacementStrength).mul(materialNormal)
  );

  material.positionNode = displacedPosition;
  material.colorNode = texture(colorMap);
  material.metalnessNode = 0.45;
  material.roughnessNode = 0.6;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene transformations
  group.position.fromArray(config.scenePosition);
  group.rotation.fromArray(config.sceneRotation);
  group.scale.fromArray(config.sceneScale);

  // Animation state
  const anim = {
    hoverActive: false,
    baseY: config.scenePosition[1],
    baseScale: config.sceneScale[0],
    hoverTL: null,
    clickTL: null,
    parallaxTL: null,
  };

  // Event handlers
  group.userData.handlers = {
    hover() {
      if (anim.hoverActive) return;
      anim.hoverActive = true;
      if (anim.hoverTL) anim.hoverTL.kill();

      anim.hoverTL = gsap.to(group.position, {
        y: anim.baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },

    unhover() {
      if (!anim.hoverActive) return;
      anim.hoverActive = false;
      if (anim.hoverTL) anim.hoverTL.kill();

      anim.hoverTL = gsap.to(group.position, {
        y: anim.baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
    },

    click() {
      if (anim.clickTL) anim.clickTL.kill();
      anim.clickTL = gsap.timeline();

      anim.clickTL.to(group.scale, {
        x: anim.baseScale * 0.97,
        y: anim.baseScale * 0.97,
        z: anim.baseScale * 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0);

      anim.clickTL.to(group.scale, {
        x: anim.baseScale,
        y: anim.baseScale,
        z: anim.baseScale,
        duration: 0.3,
        ease: 'power2.out',
      });

      if (group.userData.emit) {
        group.userData.emit('hub-features.select', {});
      }
    },

    cursorMove(ndc) {
      if (!ndc) return;
      if (anim.parallaxTL) anim.parallaxTL.kill();

      anim.parallaxTL = gsap.to(mesh.rotation, {
        x: (ndc.y || 0) * 0.03,
        y: (ndc.x || 0) * 0.03,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
  };

  // Cleanup function: dispose of resources and kill animations
  group.userData.cleanup = () => {
    if (anim.hoverTL) anim.hoverTL.kill();
    if (anim.clickTL) anim.clickTL.kill();
    if (anim.parallaxTL) anim.parallaxTL.kill();

    geometry.dispose();
    material.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  return group;
}
